
alter table public.financial_classifications add constraint financial_classifications_id_organization_id_key unique(id,organization_id);

create table if not exists public.financial_events(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,entity_id uuid,counterparty_id uuid,vat_profile_id uuid,event_type text not null,source_module text not null,source_record_id uuid,source_event_key text not null,description text not null default '',event_date date not null,due_date date,settlement_date date,status text not null default 'DRAFT',planning_view text,scenario_key text,base_currency text not null references public.currencies(code),created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),posted_by uuid references auth.users(id),posted_at timestamptz,
 unique(id,organization_id),unique(organization_id,source_module,source_event_key),
 check(event_type in('REVENUE','EXPENSE','ASSET_PURCHASE','LIABILITY','RECEIVABLE','PAYABLE','TRANSFER','SETTLEMENT','ADJUSTMENT','REVERSAL')),
 check(status in('DRAFT','PLANNED','COMMITTED','ACTUAL','CANCELLED','REVERSED'))
);
create table if not exists public.financial_event_lines(
 id uuid primary key default gen_random_uuid(),event_id uuid not null,organization_id uuid not null,line_number integer not null,description text not null default '',classification_id uuid not null,cost_center_id uuid,budget_line_id uuid,amount numeric(24,4) not null,currency text not null references public.currencies(code),exchange_rate numeric(24,10) not null,base_amount numeric(24,4) not null,cash_direction text not null,vat_treatment text not null default 'OUT_OF_SCOPE',vat_rate numeric(5,2) not null default 0,vat_amount numeric(24,4) not null default 0,recoverable_percent numeric(5,2) not null default 100,metadata jsonb not null default '{}',created_at timestamptz not null default now(),
 unique(id,organization_id),unique(event_id,line_number),
 foreign key(event_id,organization_id) references public.financial_events(id,organization_id) on delete cascade,
 foreign key(classification_id,organization_id) references public.financial_classifications(id,organization_id) on delete restrict,
 check(amount>0),check(exchange_rate>0),check(base_amount>0),check(cash_direction in('INFLOW','OUTFLOW','NON_CASH'))
);
create table if not exists public.financial_event_links(
 id uuid primary key default gen_random_uuid(),event_id uuid not null,organization_id uuid not null,link_type text not null,target_module text,target_record_id uuid,related_event_id uuid,metadata jsonb not null default '{}',created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),
 foreign key(event_id,organization_id) references public.financial_events(id,organization_id) on delete cascade
);
create table if not exists public.financial_event_approvals(
 id bigint generated by default as identity primary key,event_id uuid not null,organization_id uuid not null,approver_id uuid not null references auth.users(id),decision text not null,note text,decided_at timestamptz not null default now(),unique(event_id,approver_id),
 foreign key(event_id,organization_id) references public.financial_events(id,organization_id) on delete restrict,check(decision in('APPROVED','REJECTED'))
);
create table if not exists public.financial_event_status_history(
 id bigint generated by default as identity primary key,event_id uuid not null,organization_id uuid not null,from_status text,to_status text not null,actor_id uuid references auth.users(id),note text,changed_at timestamptz not null default now(),
 foreign key(event_id,organization_id) references public.financial_events(id,organization_id) on delete restrict
);
create table if not exists public.financial_event_command_registry(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,command_type text not null,source_module text not null,source_event_key text not null,payload_fingerprint text not null,financial_event_id uuid,canonical_payload jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,command_type,source_module,source_event_key)
);
create table if not exists public.financial_event_obligations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,event_id uuid not null,obligation_key text not null,obligation_type text not null,adjusts_obligation_id uuid,adjustment_effect text not null default 'INCREASE',settleable_amount numeric(24,4) not null,currency text not null references public.currencies(code),exchange_rate numeric(24,10) not null,base_currency text not null references public.currencies(code),settleable_base_amount numeric(24,4) not null,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(event_id,obligation_key),
 foreign key(event_id,organization_id) references public.financial_events(id,organization_id) on delete restrict
);
create table if not exists public.financial_event_obligation_allocations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,application_event_id uuid not null,obligation_id uuid not null,allocation_type text not null,source_advance_obligation_id uuid,amount numeric(24,4) not null,currency text not null references public.currencies(code),exchange_rate numeric(24,10) not null,base_currency text not null references public.currencies(code),base_amount numeric(24,4) not null,created_at timestamptz not null default now(),
 foreign key(application_event_id,organization_id) references public.financial_events(id,organization_id) on delete restrict,
 foreign key(obligation_id,organization_id) references public.financial_event_obligations(id,organization_id) on delete restrict
);
create table if not exists public.financial_vat_counterparty_map(
 organization_id uuid not null references public.organizations(id),vat_contact_id uuid not null,counterparty_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),primary key(organization_id,vat_contact_id),unique(organization_id,counterparty_id)
);
create table if not exists public.financial_vat_source_bindings(
 organization_id uuid not null references public.organizations(id),source_table text not null,source_record_id uuid not null,event_id uuid not null,canonical_payload jsonb not null,payload_fingerprint text not null,document_kind text not null,side text not null,contact_id uuid not null,entity_id uuid not null,due_date date not null,original_event_id uuid,is_alias boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),primary key(organization_id,source_table,source_record_id),
 foreign key(event_id,organization_id) references public.financial_events(id,organization_id)
);
create table if not exists public.liquidity_settlements(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,entity_id uuid,account_id uuid not null,direction text not null,settlement_date date not null,amount numeric(24,4) not null,currency text not null references public.currencies(code),exchange_rate numeric(24,10) not null,base_currency text not null references public.currencies(code),base_amount numeric(24,4) not null,source_module text not null,source_event_key text not null,financial_event_id uuid not null,status text not null default 'POSTED',payload_fingerprint text not null,reversal_of_id uuid,reversal_reason text,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),posted_by uuid not null default auth.uid() references auth.users(id),posted_at timestamptz not null default now(),reversed_by uuid references auth.users(id),reversed_at timestamptz,unique(id,organization_id),unique(organization_id,financial_event_id),unique(organization_id,source_module,source_event_key),
 foreign key(financial_event_id,organization_id) references public.financial_events(id,organization_id) on delete restrict,check(direction in('INFLOW','OUTFLOW')),check(status in('POSTED','REVERSED'))
);
create table if not exists public.liquidity_flow_settlement_allocations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,settlement_id uuid not null,flow_id uuid not null,financial_event_id uuid not null,allocation_type text not null,amount numeric(24,4) not null,currency text not null references public.currencies(code),exchange_rate numeric(24,10) not null,base_currency text not null references public.currencies(code),base_amount numeric(24,4) not null,reversal_of_allocation_id uuid,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),
 foreign key(settlement_id,organization_id) references public.liquidity_settlements(id,organization_id) on delete restrict,
 foreign key(financial_event_id,organization_id) references public.financial_events(id,organization_id) on delete restrict
);
create table if not exists public.liquidity_settlement_status_history(
 id bigint generated by default as identity primary key,organization_id uuid not null,settlement_id uuid not null,from_status text,to_status text not null,actor_id uuid references auth.users(id),reason text,changed_at timestamptz not null default now(),
 foreign key(settlement_id,organization_id) references public.liquidity_settlements(id,organization_id) on delete restrict
);
